package com.securevault.pro.data.remote.firebase

import com.google.gson.JsonParser
import com.securevault.pro.security.KeyDerivation
import java.io.File
import java.security.MessageDigest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * The other half of `svp-contract-1.json`.
 *
 * The file is generated by Node (`tools/sync-probe/vector.js`) — the maths the Blogger page runs — and
 * this test opens it with [KeyringCodec] and [KeyDerivation], the maths the APK runs. Same envelope,
 * same ciphertext, same plaintext: that is the proof the realtime sync rides the *old* encryption
 * untouched, and that a phone-written backup can still be read on the web and the other way round.
 *
 * If this test fails while `node tools/sync-probe/vector.js --check` passes, the two frontends have
 * drifted apart, and every record already in the database is at risk of becoming unreadable.
 */
class EncryptionContractVectorTest {

    private fun vector(): com.google.gson.JsonObject =
        com.google.gson.JsonParser.parseString(contractFile().readText()).asJsonObject

    @Test
    fun `the contract constants are the app's own constants`() {
        val v = vector()
        assertEquals(KeyringCodec.ALGORITHM, v["algorithm"].asString)
        assertEquals(KeyringCodec.TRANSFORMATION, v["transformation"].asString)
        assertEquals(KeyringCodec.KEY_BYTES, v["keyBytes"].asInt)
        assertEquals(KeyringCodec.IV_BYTES, v["ivBytes"].asInt)
        assertEquals(KeyringCodec.TAG_BITS, v["tagBits"].asInt)
        assertEquals("base64(iv).base64(ciphertext+tag)", v["envelopeShape"].asString)
        val pbkdf2 = v.getAsJsonObject("pbkdf2")
        assertEquals(KeyDerivation.PBKDF2_ITERATIONS, pbkdf2["iterations"].asInt)
        assertEquals(KeyDerivation.SALT_SIZE_BYTES, pbkdf2["saltBytes"].asInt)
        assertEquals(KeyDerivation.KEY_SIZE_BITS, pbkdf2["derivedKeyBytes"].asInt * 8)
        assertEquals("sha256", pbkdf2["digest"].asString)
    }

    @Test
    fun `the JVM derives the same PBKDF2 key as Node`() {
        val v = vector()
        val pbkdf2 = v.getAsJsonObject("pbkdf2")
        val salt = base64(pbkdf2["salt"].asString)
        val derived = KeyDerivation()
            .deriveKey(pbkdf2["passphraseLabel"].asString.toCharArray(), salt, pbkdf2["iterations"].asInt)
        try {
            assertEquals(KeyringCodec.KEY_BYTES, derived.size)
            assertEquals(pbkdf2["kekFingerprint"].asString, fingerprint(derived))
        } finally {
            derived.fill(0)
        }
    }

    @Test
    fun `the JVM opens the record Node sealed`() {
        val v = vector()
        val record = v.getAsJsonObject("record")
        val plain = record["plain"].asString
        val opened = KeyringCodec.openBytes(record["envelope"].asString, vaultKey())
        assertNotNull("A Node-sealed envelope must open under the app's cipher", opened)
        assertEquals(plain, String(opened!!, Charsets.UTF_8))
    }

    @Test
    fun `the JVM unwraps the keyring Node sealed`() {
        val v = vector()
        val keyring = v.getAsJsonObject("keyring")
        val salt = base64(keyring["salt"].asString)
        val unwrapped = KeyringCodec.unwrap(
            keyring["wrap"].asString,
            v.getAsJsonObject("pbkdf2")["passphraseLabel"].asString,
            salt,
            keyring["iters"].asInt
        )
        assertNotNull("The web's keyring wrap must unwrap on the phone", unwrapped)
        assertEquals(v.getAsJsonObject("vaultKey")["fingerprint"].asString, fingerprint(unwrapped!!))
    }

    @Test
    fun `a wrong passphrase yields no key and a tampered envelope yields no plaintext`() {
        val v = vector()
        val keyring = v.getAsJsonObject("keyring")
        val salt = base64(keyring["salt"].asString)
        assertNull(KeyringCodec.unwrap(keyring["wrap"].asString, "not the contract label", salt, keyring["iters"].asInt))

        val record = v.getAsJsonObject("record")
        val parts = record["envelope"].asString.split(".")
        val body = base64(parts[1])
        body[0] = (body[0].toInt() xor 0x01).toByte()
        val flipped = parts[0] + "." + KeyringCodec.encodeBase64(body)
        assertNull(KeyringCodec.openBytes(flipped, vaultKey()))
    }

    @Test
    fun `what the JVM seals, Node's envelope shape parses`() {
        val key = vaultKey()
        val envelope = KeyringCodec.sealBytes("round trip in both directions".toByteArray(), key)
        val parts = envelope.split(".")
        assertEquals(2, parts.size)
        assertEquals(KeyringCodec.IV_BYTES, base64(parts[0]).size)
        val body = base64(parts[1])
        assertEquals("round trip in both directions", String(KeyringCodec.openBytes(envelope, key)!!))
        // Ciphertext plus the 128-bit tag, exactly the layout `protocol.js` slices from the tail.
        assertEquals("round trip in both directions".toByteArray().size + KeyringCodec.TAG_BITS / 8, body.size)
    }

    @Test
    fun `the contract key is derived from its public label on both sides`() {
        assertEquals(
            vector().getAsJsonObject("vaultKey")["fingerprint"].asString,
            fingerprint(vaultKey())
        )
    }

    /** The 256-bit vault key the fixture was sealed under: sha256 of its public label. */
    private fun vaultKey(): ByteArray =
        MessageDigest.getInstance("SHA-256").digest(VAULT_KEY_LABEL.toByteArray(Charsets.UTF_8))

    private fun fingerprint(value: ByteArray): String {
        val hex = MessageDigest.getInstance("SHA-256").digest(value)
            .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
        return hex.substring(0, 16)
    }

    private fun base64(value: String): ByteArray = java.util.Base64.getDecoder().decode(value)

    private fun contractFile(): File {
        val name = "sync_engine/contract/svp-contract-1.json"
        var dir: File? = File(System.getProperty("user.dir") ?: ".").absoluteFile
        while (dir != null) {
            val candidate = File(dir, name)
            if (candidate.isFile) return candidate
            dir = dir.parentFile
        }
        throw AssertionError("missing $name — run `node tools/sync-probe/vector.js --write`")
    }

    private companion object {
        const val VAULT_KEY_LABEL = "SVP-CONTRACT-1-VAULT-KEY"
    }
}
